<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import DashboardStatCard from '@/components/DashboardStatCard.vue';
import DashboardRequestsTable from '@/components/DashboardRequestsTable.vue';
import DashboardFooter from '@/components/DashboardFooter.vue';
import DashboardLayout from '@/layouts/DashboardLayout.vue';
import ApiAlert from '@/components/ApiAlert.vue';
import { api, errorMessage } from '@/api/client';
import { requestStatuses, requestLabel } from '@/utils/requests';
import type { AdminDashboard, ApiResponse } from '@/types/api';
const data = ref<AdminDashboard | null>(null), loading = ref(true), error = ref('');
const sections = [
  { label: 'Membership applications', to: '/admin/membership', icon: 'fact_check' },
  { label: 'Alumni members', to: '/admin/alumni', icon: 'group' },
  { label: 'Announcements', to: '/admin/content/announcements', icon: 'campaign' },
  { label: 'Stories', to: '/admin/content/stories', icon: 'auto_stories' },
  { label: 'Events', to: '/admin/content/events', icon: 'event' },
  { label: 'School history', to: '/admin/content/history', icon: 'history_edu' },
  { label: 'Leadership', to: '/admin/content/leadership/school', icon: 'groups' },
  { label: 'Document requests', to: '/admin/requests', icon: 'description' },
];
const cards = computed(() => data.value ? [
 { label: 'Total Alumni', value: data.value.stats.totalApprovedAlumni, icon: 'groups', note: 'Approved memberships' },
 { label: 'Pending reviews', value: data.value.stats.pendingApplications, icon: 'fact_check', note: 'Awaiting registrar review' },
 { label: 'Published', value: data.value.stats.publishedAnnouncements, icon: 'campaign', note: 'Published announcements' },
 { label: 'Upcoming Events', value: data.value.stats.upcomingEvents, icon: 'calendar_today', note: 'Published future events' },
 { label: 'Doc Requests', value: data.value.requestsByStatus.SUBMITTED + data.value.requestsByStatus.IN_REVIEW, icon: 'pending_actions', note: 'Submitted or in review', urgent: true },
] : []);
const inProgress = computed(() => data.value ? data.value.stats.totalRequests - data.value.requestsByStatus.COMPLETED - data.value.requestsByStatus.REJECTED : 0);
const inProgressPercent = computed(() => data.value?.stats.totalRequests ? inProgress.value / data.value.stats.totalRequests * 100 : 0);
const fulfillment = computed(() => data.value?.stats.totalRequests ? Math.round(data.value.requestsByStatus.COMPLETED / data.value.stats.totalRequests * 100) : 0);
async function load() { loading.value = true; error.value = ''; try { data.value = (await api.get<ApiResponse<AdminDashboard>>('/admin/dashboard')).data.data; } catch (e) { error.value = errorMessage(e); } finally { loading.value = false; } }
onMounted(load);
</script>
<template><DashboardLayout><section class="mx-auto max-w-[1600px] space-y-8 p-4 md:p-8"><h1 class="sr-only">Administrator dashboard</h1><ApiAlert :message="error"/><p v-if="loading" role="status">Loading administrator statistics…</p><button v-if="error" class="secondary-button" @click="load">Try again</button>
<section class="flex flex-wrap items-center justify-between gap-4 rounded border border-slate-200 bg-white p-6"><div><h2 class="mb-1 text-label-sm uppercase tracking-widest text-slate-500">System Actions</h2><p class="text-body-md text-on-surface-variant">Perform priority administrative tasks</p></div><div class="flex flex-wrap gap-3"><RouterLink to="/admin/content/announcements" class="dashboard-action"><span aria-hidden="true" class="material-symbols-outlined text-xl">campaign</span>Create Announcement</RouterLink><RouterLink to="/admin/content/events" class="dashboard-action"><span aria-hidden="true" class="material-symbols-outlined text-xl">event</span>Create Event</RouterLink><RouterLink to="/admin/requests" class="dashboard-action dashboard-action-primary"><span aria-hidden="true" class="material-symbols-outlined text-xl">fact_check</span>Review Requests</RouterLink></div></section>
<template v-if="data && !loading"><div class="grid gap-6 md:grid-cols-3 lg:grid-cols-5"><DashboardStatCard v-for="card in cards" :key="card.label" v-bind="card" compact/></div><div class="grid items-stretch gap-8 lg:grid-cols-3"><DashboardRequestsTable :requests="data.recentRequests" admin class="lg:col-span-2"/><section class="rounded border border-slate-200 bg-white"><h2 class="border-b border-slate-100 px-6 py-5 text-label-sm text-primary-container">Request Fulfillment</h2><div class="flex flex-col items-center p-8"><div class="relative mb-8 h-48 w-48"><svg viewBox="0 0 36 36" class="h-full w-full -rotate-90" role="img" :aria-label="`${fulfillment}% of all requests completed`"><circle cx="18" cy="18" r="16" fill="none" stroke="#f1f5f9" stroke-width="4"/><circle cx="18" cy="18" r="16" fill="none" stroke="#1b2e4b" stroke-width="4" pathLength="100" :stroke-dasharray="`${fulfillment} ${100 - fulfillment}`"/><circle cx="18" cy="18" r="16" fill="none" stroke="#b0915d" stroke-width="4" pathLength="100" :stroke-dasharray="`${inProgressPercent} ${100 - inProgressPercent}`" :stroke-dashoffset="-fulfillment"/></svg><div aria-hidden="true" class="absolute inset-0 flex flex-col items-center justify-center"><span class="text-h2 text-primary-container">{{ fulfillment }}%</span><span class="text-[10px] font-bold uppercase text-slate-500">Completed</span></div></div><dl class="w-full space-y-4 text-caption"><div class="flex justify-between"><dt class="flex items-center gap-2"><span aria-hidden="true" class="h-3 w-3 rounded-full bg-primary-container"></span>Completed</dt><dd>{{ data.requestsByStatus.COMPLETED }}</dd></div><div class="flex justify-between"><dt class="flex items-center gap-2"><span aria-hidden="true" class="h-3 w-3 rounded-full bg-on-tertiary-container"></span>In progress</dt><dd>{{ inProgress }}</dd></div><div class="flex justify-between"><dt>All requests</dt><dd>{{ data.stats.totalRequests }}</dd></div></dl><p class="mt-4 w-full border-t pt-4 text-caption text-secondary">Completed requests divided by all requests.</p></div></section></div>
<details class="rounded border border-slate-200 bg-white p-6"><summary class="cursor-pointer text-label-sm text-primary">More school statistics and activity</summary><div class="mt-6 space-y-6"><nav class="grid gap-3 sm:grid-cols-2 lg:grid-cols-3" aria-label="Administrative sections"><RouterLink v-for="section in sections" :key="section.to" :to="section.to" class="flex items-center gap-3 border p-4 font-semibold text-primary"><span aria-hidden="true" class="material-symbols-outlined">{{ section.icon }}</span>{{ section.label }}</RouterLink></nav><div class="grid gap-4 sm:grid-cols-3"><DashboardStatCard label="Activated alumni accounts" :value="data.stats.activatedAlumniAccounts" icon="verified_user" :note="`${data.stats.activeAlumniAccounts} currently active`"/><DashboardStatCard label="Rejected applications" :value="data.stats.rejectedApplications" icon="person_off"/><DashboardStatCard label="Published stories" :value="data.stats.publishedStories" icon="auto_stories"/></div><section class="space-y-5 border bg-white p-6"><div class="flex flex-wrap justify-between gap-4"><h2 class="text-h2">Document requests by status</h2><RouterLink to="/admin/requests" class="underline">Manage requests</RouterLink></div><div class="grid gap-4 sm:grid-cols-2 lg:grid-cols-3"><div v-for="status in requestStatuses" :key="status" class="border bg-slate-50 p-4"><p class="text-xs text-secondary">{{ requestLabel(status) }}</p><p class="mt-2 text-2xl font-semibold">{{ data.requestsByStatus[status] }}</p></div></div></section>
<div class="grid items-start gap-6 lg:grid-cols-2"><section class="space-y-4 border bg-white p-6"><div class="flex flex-wrap justify-between gap-3"><h2 class="text-h2">Pending memberships</h2><RouterLink to="/admin/membership" class="underline">Review applications</RouterLink></div><article v-for="item in data.recentApplications" :key="item.id" class="space-y-1 border-t pt-4"><h3 class="font-semibold">{{ item.fullName }}</h3><p class="text-sm">Class of {{ item.graduationYear }}</p><p class="break-all text-xs text-secondary">{{ item.reference }} · {{ new Date(item.createdAt).toLocaleDateString() }}</p></article><p v-if="!data.recentApplications.length" class="text-secondary">No membership applications awaiting review.</p></section><section class="space-y-4 border bg-white p-6"><div class="flex flex-wrap justify-between gap-3"><h2 class="text-h2">Recent document requests</h2><RouterLink to="/admin/requests" class="underline">Open request management</RouterLink></div><article v-for="item in data.recentRequests" :key="item.id" class="space-y-1 border-t pt-4"><h3 class="font-semibold">{{ item.fullNameAtGraduation }}</h3><p class="text-sm">{{ requestLabel(item.requestType) }} · {{ requestLabel(item.status) }}</p><p class="break-all text-xs text-secondary">{{ item.id }} · {{ new Date(item.createdAt).toLocaleDateString() }}</p></article><p v-if="!data.recentRequests.length" class="text-secondary">No document requests yet.</p></section></div>
<section class="space-y-4 border bg-white p-6"><h2 class="text-h2">Recent membership activity</h2><ol class="space-y-4"><li v-for="activity in data.membershipActivity" :key="activity.id" class="space-y-1 border-t pt-4"><p class="font-semibold">{{ requestLabel(activity.action) }} · {{ activity.application.fullName }}</p><p class="text-xs text-secondary">{{ activity.actor?.email || 'Applicant submission / correction' }} · {{ new Date(activity.createdAt).toLocaleString() }}</p><p class="break-all text-xs">{{ activity.application.reference }}</p></li></ol><p v-if="!data.membershipActivity.length" class="text-secondary">No membership activity recorded yet.</p></section></div></details><div class="flex flex-wrap items-center justify-between gap-3 text-xs text-secondary"><p>Snapshot {{ new Date(data.asOf).toLocaleString() }}</p><button class="dashboard-action" :disabled="loading" @click="load">Refresh dashboard</button></div></template><DashboardFooter/></section></DashboardLayout></template>
